def pascal(n):
    c = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        c[i][0] = 1
        for j in range(1, i + 1):
            c[i][j] = c[i - 1][j - 1] + c[i - 1][j]
    return c

def kth(n, k, r, start, c, current):
    if k == 0:
        return current
    x = start
    while r > c[n - x][k - 1]:
        r -= c[n - x][k - 1]
        x += 1
    current.append(x)
    return kth(n, k - 1, r, x + 1, c, current)

